window.questions2021 = [
  {n:1,skill:"Multiplication",title:"Equal groups of six",en:"6 + 6 + 6 + 6 + 6 + 6 + 6 = ____ × 6. What is the missing number in the blank?",vi:"Có bao nhiêu nhóm 6 trong tổng đã cho?",answer:"7",hint:"Count how many times 6 appears.",steps:["There are 7 sixes.","7 × 6 = 42","Answer: 7"]},
  {n:2,skill:"Length",title:"Metres and centimetres",en:"9 m 3 cm = ____ cm. What is the missing number in the blank?",vi:"Đổi 9 m 3 cm sang xăng-ti-mét.",answer:"903",unit:"cm",hint:"1 m = 100 cm.",steps:["9 m = 9 × 100 cm = 900 cm","900 cm + 3 cm = 903 cm"]},
  {n:3,skill:"Division",title:"Divide 608",en:"608 ÷ 8 = ____. What is the missing number in the blank?",vi:"Tính 608 chia 8.",answer:"76",hint:"Split 608 into 560 and 48.",steps:["560 ÷ 8 = 70","48 ÷ 8 = 6","70 + 6 = 76"]},
  {n:4,skill:"Subtraction",title:"Find digit A",en:"In the subtraction 3007 - 10A9 = 191A, what digit does A represent?",vi:"Trong phép trừ đã cho, chữ số A là bao nhiêu?",answer:"8",hint:"Try the ones column first and remember to regroup.",steps:["3007 - 1089 = 1918","The same digit fills both boxes.","A = 8"]},
  {n:5,skill:"Place value",title:"Hundreds and tens",en:"What is the sum of 81 hundreds and 6 tens?",vi:"Tổng của 81 trăm và 6 chục là bao nhiêu?",answer:"8160",hint:"Write each amount as a number before adding.",steps:["81 hundreds = 8100","6 tens = 60","8100 + 60 = 8160"]},
  {n:6,skill:"Multiplication",title:"Missing factor",en:"What is the missing number? 35 × 4 = 7 × ____",vi:"Tìm thừa số còn thiếu.",answer:"20",hint:"Find 35 × 4, then divide by 7.",steps:["35 × 4 = 140","140 ÷ 7 = 20"]},
  {n:7,skill:"Fractions",title:"Shade one half",en:"The figure stands for one whole. Bala wants to shade 1/2 of the figure. How many more parts must he shade?",vi:"Bala cần tô thêm bao nhiêu phần để được một nửa hình?",answer:"2",unit:"parts",hint:"Half of 10 equal parts is 5 parts.",steps:["The whole has 10 equal parts.","1/2 of 10 = 5 parts","3 parts are already shaded.","5 - 3 = 2 parts"],image:"assets/fig-2021-07.jpg"},
  {n:8,skill:"Capacity",title:"Water in a container",en:"Look at the figure. What is the volume of the water in the container?",vi:"Đọc thể tích nước trong bình.",answer:"600",accepted:["600","600ml"],unit:"ml",hint:"The 1-litre scale is divided into equal 100 ml intervals.",steps:["1 litre = 1000 ml","The water line is at the 600 ml mark.","Answer: 600 ml"],image:"assets/fig-2021-08.jpg"},
  {n:9,skill:"Bar graph",title:"Bus and bicycle",en:"The bar graph shows how pupils travel to school. How many more pupils take the bus than the bicycle?",vi:"Biểu đồ cột cho biết các phương tiện học sinh sử dụng để đến trường. Số học sinh đi xe buýt nhiều hơn số học sinh đi xe đạp bao nhiêu em?",answer:"80",unit:"pupils",hint:"Read the two bars, then subtract.",steps:["Bus = 210 pupils","Bicycle = 130 pupils","210 - 130 = 80 pupils"],image:"assets/fig-2021-10.jpg"},
  {n:10,skill:"Bar graph",title:"Total pupils",en:"The bar graph shows how pupils travel to school. How many pupils are shown altogether?",vi:"Có tất cả bao nhiêu học sinh trong biểu đồ?",answer:"590",unit:"pupils",hint:"Add the heights of all four bars.",steps:["Bus = 210, Walk = 100","Car = 150, Bicycle = 130","210 + 100 + 150 + 130 = 590"],image:"assets/fig-2021-10.jpg"},
  {n:11,skill:"Number pattern",title:"Add 150",en:"Find the missing number: 2473, 2623, 2773, ____, 3073.",vi:"Tìm số còn thiếu trong dãy.",answer:"2923",hint:"Compare each number with the next one.",steps:["2623 - 2473 = 150","2773 + 150 = 2923","2923 + 150 = 3073"]},
  {n:12,skill:"Place value",title:"Greatest odd number",en:"Use all the digits 4, 7, 9 and 6 to form the greatest 4-digit odd number.",vi:"Dùng các chữ số đã cho để lập số lẻ lớn nhất có 4 chữ số.",answer:"9647",hint:"An odd number must end in 7 or 9. Keep the largest possible digits at the front.",steps:["Use 7 in the ones place so 9 can be first.","Arrange the other digits from greatest to least: 9, 6, 4.","The number is 9647."]},
  {n:13,skill:"Capacity",title:"Two water tanks",en:"Tank A holds 4 times as much water as Tank B. Tank B holds 500 ml. How much more water can Tank A hold than Tank B?",vi:"Bình A chứa gấp 4 lần bình B. A chứa nhiều hơn B bao nhiêu?",answer:"1500",accepted:["1500","1500ml"],unit:"ml",hint:"Find Tank A's capacity first.",steps:["Tank A: 4 × 500 = 2000 ml","Difference: 2000 - 500 = 1500 ml"]},
  {n:14,skill:"Division",title:"Cookies left over",en:"Jane had 408 cookies. She packed them equally into 9 tins. How many cookies were left unpacked?",vi:"Chia 408 chiếc bánh vào 9 hộp, còn dư bao nhiêu?",answer:"3",unit:"cookies",hint:"Find the remainder when 408 is divided by 9.",steps:["9 × 45 = 405","408 - 405 = 3","3 cookies were left."]},
  {n:15,skill:"Perimeter",title:"Three identical squares",en:"The figure is made of three identical squares. Each side is 27 cm. Find the perimeter of the figure.",vi:"Hình gồm ba hình vuông cạnh 27 cm. Tìm chu vi.",answer:"216",accepted:["216","216cm"],unit:"cm",hint:"Count only the outside sides.",steps:["There are 8 outside sides.","8 × 27 = 216 cm"],image:"assets/fig-2021-15.jpg"},
  {n:16,skill:"Money",title:"Five-cent coins",en:"How many 5-cent coins can be exchanged for a $10 note?",vi:"Đổi 10 đô-la được bao nhiêu đồng 5 xu?",answer:"200",unit:"coins",hint:"Change dollars to cents first.",steps:["$10 = 1000 cents","1000 ÷ 5 = 200 coins"]},
  {n:17,skill:"Multiplication",title:"Sweets for a class",en:"Ms Tan gave each of her 28 students 3 sweets and had 29 sweets left. How many sweets did she have at first?",vi:"Cô Tan phát mỗi học sinh 3 viên và còn 29 viên. Ban đầu có bao nhiêu?",answer:"113",unit:"sweets",hint:"Find how many sweets were given out, then add the remainder.",steps:["Sweets given: 28 × 3 = 84","Sweets at first: 84 + 29 = 113"]},
  {n:18,skill:"Equal spacing",title:"Stars in a row",en:"Stars are equally spaced. The distance from the first star to the third star is 26 cm. What is the distance from the first star to the sixth star?",vi:"Các ngôi sao cách đều. Tìm khoảng cách từ sao thứ nhất đến sao thứ sáu.",answer:"65",accepted:["65","65cm"],unit:"cm",hint:"First to third has 2 equal gaps; first to sixth has 5.",steps:["One gap: 26 ÷ 2 = 13 cm","First to sixth: 5 gaps","5 × 13 = 65 cm"],image:"assets/fig-2021-18.jpg"},
  {n:19,skill:"Comparison",title:"Three boys' lollipops",en:"Mark had 60 lollipops, 3 times as many as James. James had 28 fewer than Alvin. How many lollipops did Alvin have?",vi:"Tìm số kẹo mút của Alvin.",answer:"48",unit:"lollipops",hint:"Find James's number first.",steps:["James: 60 ÷ 3 = 20","Alvin: 20 + 28 = 48"]},
  {n:20,skill:"Money",title:"Storybook price",en:"Serene bought 3 identical storybooks and had $7 left. If she bought 5, she would be short of $23. What was the cost of one storybook?",vi:"Tìm giá của một quyển truyện.",answer:"15",accepted:["15","$15"],unit:"$",hint:"The two extra books account for the $30 difference.",steps:["Difference in money: $7 + $23 = $30","That pays for 2 books.","$30 ÷ 2 = $15"]},
  {n:21,skill:"Length",title:"Walk to school",en:"Pei Ling walked 1 km 35 m from home to the bus stop, then 785 m to school. What total distance did she travel? Give your answer in metres.",vi:"Tính tổng quãng đường từ nhà đến trường theo mét.",answer:"1820",accepted:["1820","1820m"],unit:"m",hint:"Convert 1 km 35 m to metres first.",steps:["1 km 35 m = 1035 m","1035 + 785 = 1820 m"],image:"assets/fig-2021-21.jpg"},
  {n:22,skill:"Mass",title:"Mass of Object B",en:"Study the weighing scales. What is the mass of Object B? Give your answer in grams.",vi:"Dựa vào hai cân, tìm khối lượng vật B.",answer:"1450",accepted:["1450","1450g"],unit:"g",hint:"Use the first scale to find one A, then subtract two A's from the second scale.",steps:["Two A objects weigh 350 g.","The second scale shows 1800 g.","Object B: 1800 - 350 = 1450 g"],image:"assets/fig-2021-22.jpg"},
  {n:23,skill:"Mass",title:"Chair and desk",en:"8 identical chairs are as heavy as 6 identical desks. Each desk is 12 kg. What is the total mass of one desk and one chair?",vi:"Tìm tổng khối lượng một bàn và một ghế.",answer:"21",accepted:["21","21kg"],unit:"kg",hint:"Find the total mass of 6 desks, then share it among 8 chairs.",steps:["6 desks: 6 × 12 = 72 kg","One chair: 72 ÷ 8 = 9 kg","12 + 9 = 21 kg"]},
  {n:24,skill:"Money",title:"Clarissa's change",en:"Clarissa bought noodles for $8.85 and a drink for $3.15. She paid with three $5 notes. How much change should she receive?",vi:"Clarissa nhận lại bao nhiêu tiền thừa?",answer:"3",accepted:["3","$3","3.00"],unit:"$",hint:"Find the total cost and the amount paid.",steps:["Cost: $8.85 + $3.15 = $12","Paid: 3 × $5 = $15","Change: $15 - $12 = $3"]},
  {n:25,skill:"Perimeter",title:"Rectangle and triangle",en:"The figure shows a rectangle and a triangle. Find the perimeter of the figure.",vi:"Tìm chu vi hình ghép.",answer:"40",accepted:["40","40cm"],unit:"cm",hint:"Do not count the shared 6 cm side inside the figure.",steps:["Outside sides: 6, 9, 8, 8 and 9 cm","6 + 9 + 8 + 8 + 9 = 40 cm"],image:"assets/fig-2021-25.jpg"},
  {n:26,skill:"Perimeter",title:"A longer rectangle",en:"A rectangle has breadth 70 m. Its length is 12 m longer. Find its perimeter.",vi:"Hình chữ nhật rộng 70 m, dài hơn rộng 12 m. Tìm chu vi.",answer:"304",accepted:["304","304m"],unit:"m",hint:"Find the length before using the perimeter formula.",steps:["Length: 70 + 12 = 82 m","Perimeter: 2 × (82 + 70) = 304 m"]},
  {n:27,skill:"Area",title:"School hall design",en:"A school hall measures 25 m by 9 m. An 8 m square design is drawn on the floor. What area is not covered by the design?",vi:"Tìm diện tích sàn không bị hình vuông che phủ.",answer:"161",accepted:["161","161m2","161m²"],unit:"m²",hint:"Subtract the square's area from the hall's area.",steps:["Hall area: 25 × 9 = 225 m²","Design area: 8 × 8 = 64 m²","225 - 64 = 161 m²"],image:"assets/fig-2021-27.jpg"},
  {n:28,skill:"Length",title:"Growing crocodile",en:"A baby crocodile is 75 cm long and grows 7 cm every month. How many months until it is 1 m 80 cm long?",vi:"Cá sấu dài 75 cm và mỗi tháng dài thêm 7 cm. Sau bao lâu đạt 1 m 80 cm?",answer:"15",unit:"months",hint:"Convert the target length to centimetres.",steps:["1 m 80 cm = 180 cm","Growth needed: 180 - 75 = 105 cm","105 ÷ 7 = 15 months"]},
  {n:29,skill:"Time",title:"Homework durations",en:"Aqilah did Mathematics from 2:35 p.m. to 3:02 p.m., Science from 3:15 p.m. to 4:00 p.m., and English from 4:30 p.m. to 5:10 p.m. How many minutes did she spend altogether?",vi:"Tính tổng thời gian Aqilah làm ba môn.",answer:"112",accepted:["112","112min"],unit:"min",hint:"Find each duration separately, then add.",steps:["Mathematics: 27 min","Science: 45 min","English: 40 min","27 + 45 + 40 = 112 min"],image:"assets/fig-2021-29.jpg"},
  {n:30,skill:"Capacity",title:"Water shared into pails",en:"A container held 4779 ml. After 4375 ml was poured out, the rest was shared equally among 4 pails. How much water was in each pail?",vi:"Phần nước còn lại được chia đều vào 4 xô. Mỗi xô bao nhiêu?",answer:"101",accepted:["101","101ml"],unit:"ml",hint:"Subtract first, then divide by 4.",steps:["Water left: 4779 - 4375 = 404 ml","Each pail: 404 ÷ 4 = 101 ml"]},
  {n:31,skill:"Capacity",title:"Orange juice jug",en:"A seller mixed 580 ml of syrup with 2040 ml of water. After filling a jug, 920 ml remained. What was the jug's capacity?",vi:"Tìm dung tích chiếc bình đựng nước cam.",answer:"1700",accepted:["1700","1700ml"],unit:"ml",hint:"Find the total juice, then subtract the amount left.",steps:["Total juice: 580 + 2040 = 2620 ml","Jug capacity: 2620 - 920 = 1700 ml"]},
  {n:32,skill:"Whole and parts",title:"Three boys' stickers",en:"Xavier says 42 more stickers would give him as many as Yusof. Yusof says 158 fewer would give him as many as Zack. Zack has half as many as Yusof. How many stickers do they have altogether?",vi:"Dựa vào cuộc trò chuyện, tìm tổng số nhãn dán của ba bạn.",answer:"748",unit:"stickers",hint:"If Zack is half of Yusof and also 158 fewer, the missing half is 158.",steps:["Yusof: 158 × 2 = 316","Zack: 316 ÷ 2 = 158","Xavier: 316 - 42 = 274","Total: 316 + 158 + 274 = 748"],image:"assets/fig-2021-32.jpg"},
  {n:33,skill:"Money",title:"Buying durians",en:"Uncle Ong bought durians at $7 each. He paid $100 and received $37 change. How many durians did he buy?",vi:"Chú Ong mua được bao nhiêu quả sầu riêng?",answer:"9",unit:"durians",hint:"Find how much he spent before dividing by the price of one durian.",steps:["Spent: $100 - $37 = $63","Number of durians: $63 ÷ $7 = 9"]},
  {n:34,skill:"Money",title:"Free drinks offer",en:"Popcorn costs $4.50 a box. For every 2 boxes bought, one drink is free. Mr Chew spent $252 on popcorn. How many free drinks did he receive?",vi:"Mua 2 hộp bắp rang được tặng 1 lon nước. Ông Chew nhận bao nhiêu lon?",answer:"28",unit:"cans",hint:"Find the number of popcorn boxes, then group them in twos.",steps:["Popcorn boxes: $252 ÷ $4.50 = 56","Free drinks: 56 ÷ 2 = 28 cans"],image:"assets/fig-2021-34.jpg"},
  {n:35,skill:"Algebra",title:"Star and heart",en:"A star plus a star equals a heart. A star plus a heart equals 387. What number does the heart represent?",vi:"Ngôi sao cộng ngôi sao bằng trái tim; ngôi sao cộng trái tim bằng 387. Trái tim là bao nhiêu?",answer:"258",accepted:["258","129"],hint:"Replace the heart with two stars.",steps:["Heart = 2 stars","Star + heart = 3 stars = 387","One star: 387 ÷ 3 = 129","Heart: 129 × 2 = 258","Note: the printed answer key lists 129 (the star), but the diagram asks for the heart."],image:"assets/fig-2021-35.jpg"},
  {n:36,skill:"Time",title:"Time at the library",en:"Sally left home at 10:45 a.m. and took 45 minutes to reach the library. She left at 4:30 p.m. How long did she stay? Give your answer in minutes.",vi:"Sally ở thư viện bao nhiêu phút?",answer:"300",accepted:["300","300min"],unit:"min",hint:"Find her arrival time first.",steps:["Arrival: 10:45 a.m. + 45 min = 11:30 a.m.","11:30 a.m. to 4:30 p.m. = 5 h","5 × 60 = 300 min"]},
  {n:37,skill:"Perimeter",title:"A shape of squares",en:"The figure is made of identical squares with side 3 cm. What is its perimeter?",vi:"Hình gồm các hình vuông cạnh 3 cm. Tìm chu vi.",answer:"54",accepted:["54","54cm"],unit:"cm",hint:"Trace the outside edge and count its 3 cm sections.",steps:["The outside boundary has 18 equal sections.","18 × 3 = 54 cm"],image:"assets/fig-2021-37.jpg"},
  {n:38,skill:"Number pattern",title:"Triangle rule",en:"In each triangle, the centre equals the product of the three outer numbers. What is the value of A?",vi:"Số ở giữa bằng tích ba số bên ngoài. Tìm A.",answer:"72",hint:"Use the first two triangles to see the multiplication rule.",steps:["2 × 2 × 7 = 28","2 × 3 × 8 = 48","4 × 2 × 9 = 72","A = 72"],image:"assets/fig-2021-38.jpg"},
  {n:39,skill:"Equal spacing",title:"Flower pots",en:"Flower pots are equally spaced. The first to fourth pot is 12 m; the first to last is 100 m. How many pots are there altogether?",vi:"Các chậu hoa cách đều. Tìm tổng số chậu.",answer:"26",unit:"pots",hint:"Four pots make 3 gaps. The number of pots is one more than the number of gaps.",steps:["One gap: 12 ÷ 3 = 4 m","Number of gaps: 100 ÷ 4 = 25","Number of pots: 25 + 1 = 26"],image:"assets/fig-2021-39.jpg"},
  {n:40,skill:"Problem solving",title:"Carnival scoring",en:"Ali kicked 10 balls into Hole A or B. Hole A scores 2 points and Hole B scores 4 points. He scored 26 points. How many balls went into Hole B?",vi:"Ali sút 10 quả, lỗ A được 2 điểm và B được 4 điểm. Có bao nhiêu quả vào B?",answer:"3",unit:"times",hint:"If all 10 went into A, he would score 20. Each B adds 2 more points.",steps:["All in A: 10 × 2 = 20 points","Extra points needed: 26 - 20 = 6","Each B gives 2 extra points.","6 ÷ 2 = 3 times"]},
  {n:41,skill:"Perimeter",title:"Basketball court",en:"Ben jogged twice around a rectangular court and covered 180 m. The court is 30 m long. What is its breadth?",vi:"Ben chạy hai vòng sân hình chữ nhật dài 30 m. Tìm chiều rộng.",answer:"15",accepted:["15","15m"],unit:"m",hint:"One lap is half of 180 m.",steps:["One perimeter: 180 ÷ 2 = 90 m","Length + breadth: 90 ÷ 2 = 45 m","Breadth: 45 - 30 = 15 m"],image:"assets/fig-2021-41.jpg"},
  {n:42,skill:"Division",title:"Packing pears",en:"A seller bought 6 boxes of 160 pears and packed them into bags of at most 9. What is the least number of bags needed?",vi:"Đóng 6 hộp, mỗi hộp 160 quả lê, vào túi 9 quả. Cần ít nhất bao nhiêu túi?",answer:"107",unit:"bags",hint:"A bag is still needed for any remainder.",steps:["Pears: 6 × 160 = 960","960 ÷ 9 = 106 remainder 6","So 106 full bags and 1 more bag are needed.","Least number = 107"]},
  {n:43,skill:"Money",title:"Robots and game sets",en:"Luke spent $138 on 3 toy robots and 3 game sets. Each game set cost $10 more than each robot. How much did one game set cost?",vi:"Ba robot và ba bộ trò chơi giá 138 đô-la. Một bộ trò chơi giá bao nhiêu?",answer:"28",accepted:["28","$28"],unit:"$",hint:"Divide the total into 3 identical robot-and-game pairs.",steps:["One pair: $138 ÷ 3 = $46","If robot = □, game = □ + $10.","Two equal parts: $46 - $10 = $36","Robot = $18","Game set = $18 + $10 = $28"],image:"assets/fig-2021-43.jpg"},
  {n:44,skill:"Area",title:"Area of the rectangle",en:"The figure contains a rectangle and a square of side 6 cm. The rectangle is 13 cm long. Use the marked 7 cm and 4 cm distances to find the rectangle's area.",vi:"Hình bên gồm một hình chữ nhật và một hình vuông có cạnh 6 cm. Hình chữ nhật dài 13 cm. Hãy sử dụng các số đo 7 cm và 4 cm được đánh dấu để tính diện tích hình chữ nhật.",answer:"117",accepted:["117","117cm2","117cm²"],unit:"cm²",hint:"First find how far the rectangle extends below the top of the square.",steps:["Part above the rectangle's bottom: 6 - 4 = 2 cm","Rectangle height: 7 + 2 = 9 cm","Area: 13 × 9 = 117 cm²"],image:"assets/fig-2021-44.jpg",crop:[0,300,500,410]},
  {n:45,skill:"Fractions",title:"Jan's savings",en:"Nathan's savings are $128 less than 3/4 of Jan's savings. Together they have $1867. How much money does Jan have?",vi:"Tiền của Nathan ít hơn 3/4 tiền của Jan 128 đô-la. Tìm tiền của Jan.",answer:"1140",accepted:["1140","$1140"],unit:"$",hint:"Add $128 to the total so the two amounts become 1 whole plus 3/4 of Jan's savings.",steps:["Jan + 3/4 Jan = $1867 + $128","1 3/4 Jan = $1995","1/4 Jan = $1995 ÷ 7 = $285","Jan = 4 × $285 = $1140"]}
];
